def median_ignore_none(values):
    # Check if the list is empty
    if not values:
        raise ValueError("No numbers left after ignoring None values")

    # Filter out None values from the list
    filtered_values = [x for x in values if x is not None]

    # Sort the filtered list of numbers
    sorted_values = sorted(filtered_values)

    # Determine the length of the sorted list
    n = len(sorted_values)

    # If the length is odd, return the middle element
    if n % 2 == 1:
        return float(sorted_values[n // 2])
    # If the length is even, return the average of the two middle elements
    else:
        return (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2.0

