        raise ValueError("Input must be a string in the format 'HH:MM'")

    if not re.match(r'^\d{2}:\d{2}$', text):
        raise ValueError("Invalid time format")

    hours, minutes = map(int, text.split(':'))
    return hours * 60 + minutes

import re

def slug_path(parts):
    slugged_parts = []
    for part in parts:
        slug = re.sub(r'[^a-z0-9]+', '-', part).strip('-').lower()
        if slug:
            slugged_parts.append(slug)
    if not slugged_parts:
        raise ValueError("No valid parts left after processing")
    return '/'.join(slugged_parts)

import re

def slug_path(parts):
    slugs = []
    for part in parts:
        slug = re.sub(r'[^a-z0-9]+', '-', part.lower()).strip('-')
        if slug:
            slugs.append(slug)
    if not slugs:
        raise ValueError("No valid slug parts left")
    return '/'.join(slugs)

def chunk_sums(xs, size):
    if not isinstance(size, int) or size < 1:
        raise ValueError("size must be an int >= 1")
    return [sum(xs[i:i+size]) for i in range(0, len(xs), size)]

